-- NEXORA AI v0.4 · Cloudflare D1 (SQLite) · base nueva, sin datos reales
PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS businesses(id TEXT PRIMARY KEY,name TEXT NOT NULL,sector TEXT NOT NULL DEFAULT 'general',timezone TEXT NOT NULL DEFAULT 'Europe/Madrid',language TEXT NOT NULL DEFAULT 'es',business_hours_json TEXT NOT NULL DEFAULT '{}',services_json TEXT NOT NULL DEFAULT '[]',instructions TEXT NOT NULL DEFAULT '',ai_enabled INTEGER NOT NULL DEFAULT 1 CHECK(ai_enabled IN(0,1)),outside_hours_ai_enabled INTEGER NOT NULL DEFAULT 1 CHECK(outside_hours_ai_enabled IN(0,1)),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY,auth_subject TEXT NOT NULL UNIQUE,display_name TEXT,email TEXT,platform_role TEXT NOT NULL DEFAULT 'user' CHECK(platform_role IN('user','superadmin')),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS business_memberships(business_id TEXT NOT NULL REFERENCES businesses(id) ON DELETE CASCADE,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,role TEXT NOT NULL CHECK(role IN('owner','manager','employee')),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(business_id,user_id));
CREATE TABLE IF NOT EXISTS business_modules(business_id TEXT NOT NULL REFERENCES businesses(id) ON DELETE CASCADE,module_key TEXT NOT NULL CHECK(module_key IN('whatsapp','lead_detection','owner_alerts','human_handoff','appointments','voice_reception')),enabled INTEGER NOT NULL DEFAULT 0 CHECK(enabled IN(0,1)),settings_json TEXT NOT NULL DEFAULT '{}',PRIMARY KEY(business_id,module_key));
CREATE TABLE IF NOT EXISTS contacts(id TEXT PRIMARY KEY,business_id TEXT NOT NULL REFERENCES businesses(id) ON DELETE CASCADE,display_name TEXT,phone_e164 TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(business_id,phone_e164),UNIQUE(business_id,id));
CREATE TABLE IF NOT EXISTS conversations(id TEXT PRIMARY KEY,business_id TEXT NOT NULL REFERENCES businesses(id) ON DELETE CASCADE,contact_id TEXT NOT NULL,channel TEXT NOT NULL CHECK(channel IN('web','whatsapp','voice')),status TEXT NOT NULL DEFAULT 'ai' CHECK(status IN('ai','needs_human','human','closed')),lead_status TEXT NOT NULL DEFAULT 'unknown' CHECK(lead_status IN('unknown','informational','interested')),assigned_user_id TEXT REFERENCES users(id) ON DELETE SET NULL,summary TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(business_id,contact_id) REFERENCES contacts(business_id,id),UNIQUE(business_id,id));
CREATE TABLE IF NOT EXISTS messages(id TEXT PRIMARY KEY,business_id TEXT NOT NULL,conversation_id TEXT NOT NULL,sender_type TEXT NOT NULL CHECK(sender_type IN('contact','ai','staff','system')),body TEXT NOT NULL,provider_message_id TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(business_id,conversation_id) REFERENCES conversations(business_id,id) ON DELETE CASCADE,UNIQUE(business_id,provider_message_id));
CREATE TABLE IF NOT EXISTS alerts(id TEXT PRIMARY KEY,business_id TEXT NOT NULL,conversation_id TEXT,kind TEXT NOT NULL CHECK(kind IN('urgent','handoff','daily_summary','lead')),priority TEXT NOT NULL DEFAULT 'normal' CHECK(priority IN('normal','urgent')),delivery_status TEXT NOT NULL DEFAULT 'pending' CHECK(delivery_status IN('pending','sent','failed','cancelled')),not_before TEXT,payload_json TEXT NOT NULL DEFAULT '{}',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,sent_at TEXT,FOREIGN KEY(business_id,conversation_id) REFERENCES conversations(business_id,id));
CREATE TABLE IF NOT EXISTS appointments(id TEXT PRIMARY KEY,business_id TEXT NOT NULL REFERENCES businesses(id) ON DELETE CASCADE,contact_id TEXT NOT NULL,conversation_id TEXT,service_name TEXT NOT NULL,starts_at TEXT NOT NULL,ends_at TEXT NOT NULL,timezone TEXT NOT NULL DEFAULT 'Europe/Madrid',status TEXT NOT NULL DEFAULT 'requested' CHECK(status IN('requested','confirmed','cancelled','completed')),external_calendar_event_id TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(business_id,contact_id) REFERENCES contacts(business_id,id),FOREIGN KEY(business_id,conversation_id) REFERENCES conversations(business_id,id));
CREATE TABLE IF NOT EXISTS calls(id TEXT PRIMARY KEY,business_id TEXT NOT NULL REFERENCES businesses(id) ON DELETE CASCADE,conversation_id TEXT,provider_call_id TEXT,from_number TEXT,status TEXT NOT NULL DEFAULT 'received' CHECK(status IN('received','answered','completed','failed')),summary TEXT,started_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,ended_at TEXT,FOREIGN KEY(business_id,conversation_id) REFERENCES conversations(business_id,id),UNIQUE(business_id,provider_call_id));
CREATE INDEX IF NOT EXISTS idx_memberships_user ON business_memberships(user_id);
CREATE INDEX IF NOT EXISTS idx_contacts_business ON contacts(business_id);
CREATE INDEX IF NOT EXISTS idx_conversations_business_status ON conversations(business_id,status,updated_at);
CREATE INDEX IF NOT EXISTS idx_messages_conversation ON messages(business_id,conversation_id,created_at);
CREATE INDEX IF NOT EXISTS idx_alerts_pending ON alerts(delivery_status,not_before);
CREATE INDEX IF NOT EXISTS idx_appointments_business_start ON appointments(business_id,starts_at);
CREATE INDEX IF NOT EXISTS idx_calls_business_start ON calls(business_id,started_at);
